<?php
declare(strict_types=1);namespace App\Http\Controllers\Hrd;use App\Http\Controllers\Controller;use App\Http\Requests\Hrd\StorePayrollRequest;use App\Models\{Personnel,PersonnelPayroll,SchoolProfile};use App\Services\Hrd\{CashAdvanceService,PayrollCalculator};use App\Services\Settings\ApplicationSettingService;use Carbon\CarbonImmutable;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class PersonnelPayrollController extends Controller{private function own(PersonnelPayroll$p,Request$r):void{if(!$r->user()->can('personnel-payroll.view')&&$p->personnel_id!==$r->user()->personnel?->id)abort(403);}public function index(Request$r):View{$q=PersonnelPayroll::with('personnel')->latest('period_start');if(!$r->user()->can('personnel-payroll.view')){$p=$r->user()->personnel;if(!$p)abort(403);$q->where('personnel_id',$p->id);}return view('hrd.payroll.index',['title'=>'Payroll & Gaji','payrolls'=>$q->paginate(20),'personnel'=>Personnel::where('is_active',true)->orderBy('full_name')->get()]);}public function store(StorePayrollRequest$r,PayrollCalculator$c,CashAdvanceService$cash,ApplicationSettingService$settings):RedirectResponse{$v=$r->validated();$p=Personnel::findOrFail($v['personnel_id']);$x=$c->calculate($p,CarbonImmutable::parse($v['period_start']),CarbonImmutable::parse($v['period_end']),(float)($v['allowance']??0),(float)($v['deduction']??0));DB::transaction(function()use($p,$v,$x,$r,$cash,$settings):void{$advances=$settings->get('hrd_payroll_auto_cash_advance_deduction_enabled',false)?$p->cashAdvances()->whereIn('status',['disbursed','partially_paid'])->lockForUpdate()->get():collect();$cashDeduction=$advances->sum(fn($a):float=>min((float)$a->remaining_amount,(float)$a->installment_amount));$payroll=PersonnelPayroll::create(['personnel_id'=>$p->id,'period_start'=>$v['period_start'],'period_end'=>$v['period_end'],'pay_date'=>$v['pay_date']??null,'monthly_salary'=>$x['monthly'],'base_salary'=>$x['base'],'attendance_days'=>$x['days'],'daily_salary'=>$x['daily'],'allowance'=>$x['allowance'],'deduction'=>$x['deduction'],'late_deduction'=>$x['late'],'cash_advance_deduction'=>$cashDeduction,'total'=>max(0,$x['total']-$cashDeduction),'status'=>'processed','note'=>$v['note']??null,'created_by'=>$r->user()->id]);foreach($advances as$a){$amount=min((float)$a->remaining_amount,(float)$a->installment_amount);if($amount>0)$cash->pay($a,$amount,'payroll_deduction',$r->user(),$payroll->id);}activity('hrd')->causedBy($r->user())->performedOn($payroll)->log('HRD memproses payroll.');});return back()->with('status','Payroll berhasil diproses.');}public function show(PersonnelPayroll$p,Request$r):View{$this->own($p,$r);return view('hrd.payroll.show',['title'=>'Slip Gaji','payroll'=>$p->load('personnel'),'school'=>SchoolProfile::query()->first()]);}public function print(PersonnelPayroll$p,Request$r):View{$this->own($p,$r);return view('hrd.payroll.print',['title'=>'Slip Gaji','payroll'=>$p->load('personnel'),'school'=>SchoolProfile::query()->first()]);}}
